using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence; namespace OrcaFacil.Web.Pages.ReleaseNotes; public sealed class IndexModel(OrcaFacilDbContext db):PageModel {public IReadOnlyList<ReleaseNote> Items{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct)=>Items=await db.ReleaseNotes.AsNoTracking().Where(x=>x.IsPublished&&!x.IsDeleted&&x.ReleasedAt<=DateTime.UtcNow).OrderByDescending(x=>x.ReleasedAt).ToListAsync(ct);}
